<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Sorting Visualizer</title>
    <style>
        :root {
            --bg-color: #232527;
            --text-color: #f0f2f5;
            --primary-btn-bg: #091e42;
            --primary-btn-hover: #18365b;
            --bar-default: #4da6ff;
            --bar-comparing: #ffc107;
            --bar-swapping: #dc3545;
            --bar-sorted: #28a745;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            margin: 0;
            padding: 20px;
        }

        h1 { margin-bottom: 10px; font-weight: 400; }

        .controls {
            display: flex;
            gap: 10px;
            margin-bottom: 20px;
            flex-wrap: wrap;
            justify-content: center;
        }

        button {
            background-color: var(--primary-btn-bg);
            color: white;
            border: 1px solid rgba(255,255,255,0.2);
            padding: 10px 20px;
            font-size: 1rem;
            cursor: pointer;
            border-radius: 6px;
            transition: background-color 0.2s ease, transform 0.1s;
        }

        button:hover { background-color: var(--primary-btn-hover); }
        button:active { transform: translateY(1px); }

        #bars {
            display: flex;
            align-items: flex-end; /* Align bars to bottom */
            height: 350px;
            width: 90vw;
            max-width: 800px;
            gap: 2px;
            border-bottom: 1px solid rgba(255,255,255,0.1);
            padding-bottom: 4px;
            box-sizing: border-box;
        }

        .bar {
            flex: 1; /* Distribute width */
            min-width: 3px;
            margin-bottom: 2px;
            border-radius: 0 0 4px 4px;
            transition: height 0.3s ease, background-color 0.3s ease;
            opacity: 1;
        }

        /* Animation Classes */
        .bar-comparing {
            background-color: var(--bar-comparing) !important;
            opacity: 0.9;
        }

        .bar-swapping {
            background-color: var(--bar-swapping) !important;
            opacity: 1;
        }

        .bar-sorted {
            background-color: var(--bar-sorted) !important;
        }
    </style>
</head>
<body>

    <h1>Sorting Visualizer</h1>

    <div class="controls">
        <button id="sort">Sort Step</button>
        <button id="shuffle">Shuffle</button>
        <button id="reset">Reset</button>
    </div>

    <div id="bars"></div>

<script>
(function() {
    // --- Configuration & State ---
    const BAR_COUNT = 40;
    let currentArray = [];
    const container = document.getElementById('bars');

    // Bubble Sort Logic State
    let sortState = {
        i: 0,       // Outer loop index (pass)
        j: 0,       // Inner loop index
        n: 0,       // Length of array
        passed: false // Flag to handle optimization or state reset
    };

    // --- DOM Utilities ---

    /**
     * Updates the visual height and color of a specific bar element.
     */
    function updateBarVisuals(barElement, value, isSorted) {
        if (!barElement) return;

        // Normalize value to 0-100% for height (capped at 100%)
        let percentHeight = Math.min(value, 100);
        barElement.style.height = percentHeight + '%';

        // Reset classes to apply base state
        barElement.classList.remove('bar-comparing', 'bar-swapping', 'bar-sorted');

        if (isSorted) {
            barElement.classList.add('bar-sorted');
        } else {
            barElement.style.backgroundColor = 'var(--bar-default)'; // Default color
        }
    }

    /**
     * Draws the bars based on currentArray.
     */
    function drawBars() {
        container.innerHTML = '';

        // Create DOM elements for each value in currentArray
        currentArray.forEach(val => {
            const bar = document.createElement('div');
            bar.className = 'bar';
            // Update visuals immediately after creation
            updateBarVisuals(bar, val, false);

            container.appendChild(bar);
        });

        // Store references for future updates (or just rely on innerHTML replacement if fast)
        // Since we animate via transitions, replacing innerHTML breaks animation.
        // We'll keep an array of bar elements if needed, but updating specific ones by index is hard without refs.
        // To support DOM manipulation inside sortStep efficiently, let's keep the ref array.
    }

    // Keep reference to bar elements for efficient updates (avoiding full redraw)
    const barRefs = [];

    /**
     * Updates visuals for a specific range or single bars efficiently.
     */
    function updateBarVisualsEfficient(index, value, isSorted) {
        if (!barRefs[index]) return;
        const bar = barRefs[index];

        let percentHeight = Math.min(value, 100);
        bar.style.height = percentHeight + '%';

        bar.classList.remove('bar-comparing', 'bar-swapping', 'bar-sorted');
        if (isSorted) {
            bar.classList.add('bar-sorted');
        } else {
            // We can set default color or keep previous
            // For swap animation, we might want to flash the changing bars.
            bar.style.backgroundColor = 'var(--bar-default)'; 
        }
    }

    /**
     * Clears highlights (comparing/swapping classes).
     */
    function clearHighlights() {
        for (let i = 0; i < currentArray.length; i++) {
            const bar = barRefs[i];
            if (bar) {
                // Reset height logic just in case, though mainly color
                bar.style.backgroundColor = 'var(--bar-default)';
                bar.classList.remove('bar-comparing', 'bar-swapping');
            }
        }
    }

    /**
     * Highlights bars at specific indices for visualization.
     */
    function highlightBars(i1, i2) {
        clearHighlights(); // Clear previous step highlights
        if (barRefs[i1]) barRefs[i1].classList.add('bar-comparing');
        if (barRefs[i2]) barRefs[i2].classList.add('bar-comparing');
    }

    /**
     * Checks if array is sorted ascending.
     */
    function checkSorted() {
        for (let i = 0; i < currentArray.length - 1; i++) {
            if (currentArray[i] > currentArray[i + 1]) return false;
        }
        return true;
    }

    /**
     * Initializes the API on window.
     */
    const viz = {
        // Getter: returns a copy of current array
        array: () => [...currentArray],

        // Setter: set array values and redraw DOM
        setArray: (arr) => {
            currentArray = [...arr];

            // Reset sort logic state to ensure fresh start with new data
            sortState.i = 0;
            sortState.j = 0;

            // Initial draw
            barRefs.length = 0; 
            drawBars();
        },

        // Returns boolean: is array fully sorted ascending?
        sorted: () => checkSorted(),

        // Performs one step of the sorting algorithm.
        // Returns true if the array is currently fully sorted (or sort complete).
        sortStep: () => {
            if (currentArray.length === 0) return true;

            const n = currentArray.length;

            // We use a simple Bubble Sort implementation with state tracking.
            // Logic: Iterate i from 0 to n-1. Inner loop j from 0 to n-i-2.
            // Check if we can advance inner loop.

            // Determine range limit for current pass 'i'
            const maxJ = n - 1 - sortState.i;

            // If we finished the outer pass (reached end of sorted elements)
            // Note: Standard bubble sort optimization would check if swap occurred.
            // Here we stick to standard loops for simplicity, unless sorted is checked via API.

            if (sortState.i >= n - 1) return true;

            // If we are inside the inner loop logic
            if (sortState.j < maxJ) {
                const idxA = sortState.j;
                const idxB = sortState.j + 1;

                // Visual feedback: Highlight comparison
                highlightBars(idxA, idxB);

                // Perform comparison and swap if needed
                if (currentArray[idxA] > currentArray[idxB]) {
                    // Swap logic
                    let temp = currentArray[idxA];
                    currentArray[idxA] = currentArray[idxB];
                    currentArray[idxB] = temp;

                    // Update visuals for swapped bars
                    updateBarVisualsEfficient(idxA, currentArray[idxA], false);
                    updateBarVisualsEfficient(idxB, currentArray[idxB], false);
                }

                // Move to next comparison in pass
                sortState.j++;
            } else {
                // Inner loop finished for this pass 'i'
                sortState.i++;
                sortState.j = 0; // Reset inner counter

                // Clear highlights for next step
                clearHighlights();
            }

            // Check if array is fully sorted. 
            // If it is, we signal completion.
            return viz.sorted();
        }
    };

    // --- Initialization ---

    // Set initial data (simple small array for demo)
    const initialData = [10, 50, 20, 30]; 
    viz.setArray(initialData);

    // --- Event Listeners ---

    document.getElementById('shuffle').addEventListener('click', () => {
        const newValues = [];
        for(let i=0; i<BAR_COUNT; i++) {
            newValues.push(Math.floor(Math.random() * 100));
        }
        viz.setArray(newValues);
    });

    document.getElementById('reset').addEventListener('click', () => {
        // Reset to initial state or clear? Usually reset implies clearing or restarting.
        // Let's restart with simple values.
        viz.setArray([10, 50, 20, 30]);
    });

    document.getElementById('sort').addEventListener('click', () => {
        // Button logic: animate to completion
        // We loop until sorted() is true.
        while (!viz.sorted()) {
            viz.sortStep();
        }
    });

})();
</script>
</body>
</html>
